    if raw is None or (isinstance(raw, float) and math.isnan(raw)):
        return []
    text=str(raw)
    parts=[p.strip() for p in sep_re.split(text) if p and p.strip()]
    filtered=[]
    for p in parts:
        if re.search(r'Station=|FailCode=|FailCode|Station', p, re.IGNORECASE):
            continue
        filtered.append(p)
    return filtered


def has_reason_signal(text):
    if not text: return False
    t=normalize_text(text).lower()
