comp_token_re = re.compile(r'\b([A-Z]{1,3}\d{1,4}|[A-Z0-9]+_[A-Z0-9_]+)\b')

replace_map={'短露':'短路','虚汉':'虚焊','开鲁':'开路'}

def normalize_text(text):
    t=str(text)
    for k,v in replace_map.items():
        t=t.replace(k,v)
    return t

category_synonyms = {
