# extra tokens from standard_label

def extra_label_tokens(label):
    l=label.lower()
    extras=[]
    if 'fixture contact' in l:
        extras.extend(['fixture contact','contact unstable'])
    if 'probe worn' in l:
        extras.append('probe worn')
    if 'programming failed' in l:
        extras.extend(['programming failed','flash write','reflash','reprogram'])
    if 'boot failed' in l:
        extras.extend(['boot fail','os fail','cannot boot','stuck'])
    if 'firmware verify failed' in l or 'checksum' in l:
        extras.extend(['verify failed','checksum','crc'])
    if 'hi-pot leakage' in l:
        extras.extend(['hipot leakage','leakage'])
    if 'idle current high' in l:
        extras.append('idle current high')
    if 'pressure mark' in l:
        extras.append('pressure mark')
    if 'contamination' in l:
        extras.append('contamination')
    if 'connector wear' in l:
        extras.extend(['connector wear','insertion loss'])
    if 'calibration data' in l:
        extras.extend(['cal data','rf cal','calibration data','nv write'])
    if 'esd' in l:
        extras.append('esd')
    if 'missing component' in l:
        extras.append('missing component')
    if 'component reversed' in l or 'polarity' in l:
        extras.extend(['reversed','polarity'])
    if 'open circuit' in l:
        extras.extend(['open','open circuit'])
    if 'short circuit' in l:
        extras.extend(['short','short circuit','solder bridge'])
    if 'cold solder' in l:
        extras.append('cold solder')
    return extras


def tokenize_entry(row):
    tokens=[]
    for part in str(row['keywords_examples']).split(','):
        t=part.strip()
        if t:
            tokens.append(t)
    for t in comp_token_re.findall(str(row['standard_label'])):
        tokens.append(t)
    tokens.extend(extra_label_tokens(str(row['standard_label'])))
    # add category synonyms
    cat=row.get('category_lv2','')
    if cat in category_synonyms:
        tokens.extend(category_synonyms[cat])
    # dedupe
    uniq=[]; seen=set()
    for t in tokens:
        if t.lower() in seen: continue
        seen.add(t.lower()); uniq.append(t)
    return uniq

# strong/weak tokens
weak_tokens=set(['fixture','pogo','pin','probe','contact','clamp','program','programming','flash','boot','os','verify','current','high','leakage','pressure','pad','damage','contamination','residue','connector','wear','cal','data','handling','issue','loss'])
strong_tokens=set(['open','short','crc','checksum','esd','hipot','high_res','cold solder','pressure mark','probe worn','fixture contact','boot fail','os fail','programming failed','flash write','idle current high','missing component','reversed','polarity','contamination','connector wear','cal data','rf cal','short circuit','open circuit','fixture contact unstable','contact unstable','insertion loss','solder bridge','version mismatch','boot failed','flash fail','current high','leakage','calibration data'])


def is_strong(tok):
    tl=tok.lower()
    if re.search(r'[\u4e00-\u9fff]', tok):
        return True
    if tl in strong_tokens:
        return True
    if ' ' in tok:
        return True
    if tl in weak_tokens:
        return False
    return len(tok) >=6

entries_by_product={}
for pid, df in codebooks.items():
    entries=[]
    for _, row in df.iterrows():
        tokens=tokenize_entry(row)
        comp_tokens=[t for t in tokens if comp_token_re.fullmatch(t)]
        cat_tokens=[t for t in tokens if t not in comp_tokens]
        strong=[t for t in cat_tokens if is_strong(t)]
        weak=[t for t in cat_tokens if not is_strong(t)]
        entries.append({
            'code': row['code'],
            'label': row['standard_label'],
            'station_scope': row['station_scope'],
            'comp_tokens': comp_tokens,
            'strong_tokens': strong,
            'weak_tokens': weak,
        })
    entries_by_product[pid]=entries

sep_re = re.compile(r'[；;,，。]|\bthen\b|\band\b|&', re.IGNORECASE)

def split_segments(raw):
    if raw is None or (isinstance(raw, float) and math.isnan(raw)):
        return []
    text=str(raw)
    parts=[p.strip() for p in sep_re.split(text) if p and p.strip()]
    filtered=[]
    for p in parts:
        if re.search(r'Station=|FailCode=|FailCode|Station', p, re.IGNORECASE):
            continue
        filtered.append(p)
    return filtered

# reason signal keywords (strict)
reason_kw = set([k.lower() for k in [
    'open','开路','short','短路','bridge','solder bridge','cold solder','虚焊','浮高','少锡','missing','少件','reversed','反向','polarity',
    'fixture contact','pogo','接触不良','探针','reseat','probe worn','pin','flash','烧录失败','write fail','program fail','boot fail','os fail','启动失败','stuck',
    'checksum','crc','校验失败','verify fail','leakage','漏电','绝缘不良','hipot','current high','静态电流','功耗高','pressure mark','压伤','pad damage',
    'contamination','residue','助焊剂','清洗','connector wear','sma','插拔','insertion loss','cal data','rf cal','校准数据','nv write','high_res','esd','静电','reflash','重烧','重刷','重烧不稳定','版本不符','version mismatch','下错程序','程序版本','校准失败','污染'
]])

def has_reason_signal(text):
    if not text: return False
    t=normalize_text(text).lower()
    if comp_token_re.search(text):
        return True
    for kw in reason_kw:
        if kw in t:
            return True
    return False


def match_entry(text, product_id, station):
    entries = entries_by_product[product_id]
    t_norm = normalize_text(text).lower()
    best=None; best_score=-1
    for e in entries:
        comp_hits=0
        for tok in e['comp_tokens']:
            if tok.lower() in t_norm:
                comp_hits += 1
        if e['comp_tokens']:
            comp_score = comp_hits / len(e['comp_tokens'])
        else:
            comp_score = None
        strong_hit = any(tok.lower() in t_norm for tok in e['strong_tokens'])
        weak_hit = any(tok.lower() in t_norm for tok in e['weak_tokens'])
        if strong_hit:
            cat_score = 1.0
        elif weak_hit:
            cat_score = 0.5
        else:
            cat_score = 0.0
        if comp_score is None:
            score = cat_score
        else:
            score = 0.6*comp_score + 0.4*cat_score
        if station and station in str(e['station_scope']).split(';'):
            score += 0.05
        if score > best_score:
            best_score=score; best=e
    return best, best_score

# Evaluate
threshold=0.55
unknown=0; count=0
for _, row in logs.iterrows():
    for seg in split_segments(row['raw_reason_text']):
        if not has_reason_signal(seg):
            continue
        count+=1
        e,score=match_entry(seg, row['product_id'], row['station'])
        if score < threshold:
            unknown+=1
print('segments',count,'unknown rate',unknown/count)

